import json, time, urllib.parse, urllib.request
DOIS = ["10.1126/science.1185718","10.1016/0030-5073(78)90037-5","10.1037/0033-2909.84.1.158",
        "10.1007/s11127-008-9378-7","10.2307/2527413","10.1007/s003550050118",
        "10.1037/a0015145","10.1287/mnsc.1050.0459","10.1037/a0036677","10.1287/mnsc.2014.1909",
        "10.1073/pnas.1601827113","10.1038/nature21054","10.1080/0022250x.1978.9989880",
        "10.1016/j.jebo.2021.03.029","10.1016/0749-5978(89)90055-1"]
def fetch(doi):
    url="https://api.crossref.org/works/"+urllib.parse.quote(doi)
    req=urllib.request.Request(url,headers={"User-Agent":"nc/1.0 (mailto:[email redacted])"})
    for _ in range(3):
        try:
            with urllib.request.urlopen(req,timeout=30) as r: return json.loads(r.read().decode())["message"]
        except Exception as e: err=e; time.sleep(2)
    return {"__err__":str(err)}
for doi in DOIS:
    m=fetch(doi)
    if "__err__" in m:
        print(f"!! {doi} ERROR {m['__err__']}"); continue
    t=(m.get('title') or [''])[0]; yr=None
    for k in ("published-print","published-online","issued","created"):
        if m.get(k,{}).get('date-parts'): yr=m[k]['date-parts'][0][0]; break
    au=[f"{a.get('family','')} {a.get('given','')[:1]}." for a in (m.get('author') or [])]
    print(f"{doi}\n  {yr} | {t}\n  {'; '.join(au[:6])} | {(m.get('container-title') or [''])[0]} | cited={m.get('is-referenced-by-count')}")
    time.sleep(0.8)
EOF

